package golang

const genericInboundLimitsConsumer = `package runtime
import("context";"fmt";"io";"net/http/httptest";"strings";"sync/atomic";"testing";"example.test/consumer/api/types")
type limitBody struct{io.Reader;read,closes atomic.Int64}
func(body *limitBody)Read(buffer []byte)(int,error){n,err:=body.Reader.Read(buffer);body.read.Add(int64(n));return n,err}
func(body *limitBody)Close()error{body.closes.Add(1);return nil}
func TestDefaultCompleteBodyByteLimit(t *testing.T){root,_:=types.ParseValue([]byte("{\"types\":[\"string\"]}"));contract,err:=CompileSchema(root,nil);if err!=nil{t.Fatal(err)};handler,err:=NewHandler("/",Definition{Method:"POST"},Options{},func(execution *Execution,_ ParameterResult)(Response,error){if _,err:=contract.DecodeInbound(execution,"application/json","json");err!=nil{return Response{},err};return Response{Status:204},nil});if err!=nil{t.Fatal(err)};maximum:=8*1024*1024;for _,test:=range []struct{size,status int}{ {maximum,204},{maximum+1,413} }{body:=&limitBody{Reader:strings.NewReader("\""+strings.Repeat("x",test.size-2)+"\"")};request:=httptest.NewRequest("POST","/",body);request.ContentLength=-1;request.Header.Set("Content-Type","application/json");recorder:=httptest.NewRecorder();handler.ServeHTTP(recorder,request);if recorder.Code!=test.status||body.read.Load()!=int64(test.size)||body.closes.Load()!=1{t.Fatal(test,recorder.Code,body.read.Load(),body.closes.Load(),recorder.Body.String())}}}
func TestDefaultFrameBoundAndNoAggregateStreamLimit(t *testing.T){maximum:=1024*1024;for _,test:=range []struct{name string;size,frames,frameLimit,status int}{ {"exact-frame",maximum,1,0,204},{"oversized-frame",maximum+1,1,0,400},{"over-8MiB-stream",maximum,10,0,204},{"required-empty",0,0,0,400},{"utf8-exact",4,1,4,204},{"utf8-over",4,1,3,400} }{t.Run(test.name,func(t *testing.T){calls:=0;handler,err:=NewHandler("/",Definition{Method:"POST",Streaming:func(string)bool{return true}},Options{MaxBodyBytes:32,MaxStreamFrameBytes:test.frameLimit},func(execution *Execution,_ ParameterResult)(Response,error){identity:=func(_ context.Context,value types.Value)(types.Value,error){if value.Kind()!=types.ValueString{return types.Value{},fmt.Errorf("expected string")};return value,nil};source,err:=DecodeSource(execution,"application/x-ndjson",JSONProtocol{},identity,identity,true);if err!=nil{return Response{},err};for source.Next(){calls++};return Response{Status:204},nil});if err!=nil{t.Fatal(err)};frames:=make([]io.Reader,0,test.frames);for i:=0;i<test.frames;i++{text:="\""+strings.Repeat("x",test.size-2)+"\"\n";if test.frameLimit!=0{text="\"é\"\n"};frames=append(frames,strings.NewReader(text))};body:=&limitBody{Reader:io.MultiReader(frames...)};request:=httptest.NewRequest("POST","/",body);request.Header.Set("Content-Type","application/x-ndjson");request.ContentLength=-1;recorder:=httptest.NewRecorder();handler.ServeHTTP(recorder,request);if recorder.Code!=test.status||body.closes.Load()!=1{t.Fatal(recorder.Code,body.closes.Load(),recorder.Body.String())};if test.status==204&&calls!=test.frames{t.Fatal("lost frames",calls,test.frames)};if test.name=="over-8MiB-stream"&&body.read.Load()<=8*1024*1024{t.Fatal("aggregate stream not exercised",body.read.Load())}})}}
`
